export const STEP = 10; // minutes per sample
export const PER_DAY = 144;
export const DAYS = 30;
export const N = DAYS * PER_DAY;
export const TODAY = DAYS - 1;
export const MD0 = 155; // mission day of dataset day 0  -> today is MD 184
export const NOW_MIN = 11 * 60 + 22;
export const NOW = TODAY * PER_DAY + Math.floor(NOW_MIN / STEP);
export const MISSION_DAY = MD0 + TODAY;

function mulberry32(a: number) {
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
const rnd = mulberry32(184);
const gauss = () => {
  let u = 0;
  for (let i = 0; i < 4; i++) u += rnd();
  return (u - 2) * 1.2;
};

export const idx = (day: number, min: number) => day * PER_DAY + Math.floor(min / STEP);
export const dayOf = (i: number) => Math.floor(i / PER_DAY);
export const minOf = (i: number) => (i % PER_DAY) * STEP;
export const hhmm = (min: number) => {
  const m = ((Math.round(min) % 1440) + 1440) % 1440;
  return `${String(Math.floor(m / 60)).padStart(2, "0")}:${String(m % 60).padStart(2, "0")}`;
};
export const fmtIdx = (i: number, withDay = false) =>
  (withDay ? `MD ${MD0 + dayOf(i)} · ` : "") + hhmm(minOf(i));
export const mdLabel = (day: number) => `MD ${MD0 + day}`;

