// ------------------------------------------------------------------ series --
export const S: Record<string, Float32Array> = {};
const mk = (id: string) => (S[id] = new Float32Array(N));

const ENV_BASE: Record<ModuleId, { co2: number; noise: number; temp: number; hum: number; light: number }> = {
  service: { co2: 2.3, noise: 62, temp: 24.1, hum: 38, light: 300 },
  quarters: { co2: 2.4, noise: 47, temp: 21.6, hum: 43, light: 140 },
  node: { co2: 2.2, noise: 55, temp: 22.6, hum: 42, light: 380 },
  work: { co2: 2.3, noise: 54, temp: 22.8, hum: 41, light: 480 },
  command: { co2: 2.2, noise: 53, temp: 22.4, hum: 40, light: 320 },
  lab: { co2: 2.2, noise: 57, temp: 23.0, hum: 41, light: 520 },
  galley: { co2: 2.4, noise: 56, temp: 23.2, hum: 46, light: 420 },
  exercise: { co2: 2.5, noise: 58, temp: 22.9, hum: 44, light: 450 },
  med: { co2: 2.2, noise: 50, temp: 22.5, hum: 41, light: 500 },
  airlock: { co2: 2.3, noise: 55, temp: 21.8, hum: 39, light: 350 },
};
export const ENV_PARAMS = ["co2", "noise", "temp", "hum", "light", "vib"] as const;
export type EnvParam = (typeof ENV_PARAMS)[number];

for (const m of MODULES) for (const p of ENV_PARAMS) mk(`${p}_${m.id}`);
[
  "fan", "cdra", "pump", "cmg", "thr", "power", "loop", "link", "oga", "wpa", "att",
  "pressure", "ppo2", "rad",
  "hr", "hrv", "spo2", "resp", "temp", "move", "stress", "fatigue",
].forEach(mk);

// --- pass 1: engineering + environment ------------------------------------
{
  let labCo2 = 2.2;
  let cmg = 20;
  let exVib = 0;
  const desatSet = new Map<number, number>();
  DESAT.forEach((t) => {
    for (let k = 0; k < 2; k++) desatSet.set(t + k, k);
  });
  for (let i = 0; i < N; i++) {
    const d = dayOf(i);
    const m = minOf(i);
    const blk = blockAt(i);
    const fanOn = FAN_NIGHTS.has(d) && m >= 110 && m < 150; // 01:50–02:30
    const weak = WEAK_SCRUB_DAYS.has(d) && m >= 360 && m < 1200;
    const desat = desatSet.has(i);
    const nightQuiet = m < 390 || m >= 1350;
    // engineering
    S.fan[i] = (fanOn ? 3420 : 2380) + gauss() * 18;
    S.cdra[i] = (weak ? 68 : 100) + gauss() * 0.8;
    S.pump[i] = 11800 + (fanOn ? 600 : 0) + Math.sin(i / 23) * 60 + gauss() * 25;
    cmg += 0.32 + gauss() * 0.05;
    if (desat) cmg = Math.max(8, cmg - 34);
    S.cmg[i] = Math.min(96, cmg);
    S.thr[i] = desat ? 14 + Math.round(rnd() * 6) : 0;
    S.att[i] = (desat ? 0.42 : 0.04) + Math.abs(gauss()) * 0.02;
    const exNow = blk.activity === "exercise" || (m >= 500 && m < 590) || (m >= 705 && m < 790 && d % 2 === 0);
    const wpaOn = (m >= 240 && m < 330) || (m >= 780 && m < 870) || (m >= 1230 && m < 1320);
    S.wpa[i] = wpaOn ? 1 : 0;
    S.oga[i] = 64 + (m > 420 && m < 1300 ? 10 : 0) + gauss() * 1.2;
    S.power[i] =
      13.2 + (nightQuiet ? -1.6 : 1.2) + (fanOn ? 0.9 : 0) + (wpaOn ? 0.5 : 0) + (exNow ? 0.4 : 0) +
      (m >= 495 && m < 1050 ? 1.4 : 0) + gauss() * 0.15;
    S.loop[i] = 4.3 + (S.power[i] - 13) * 0.12 + gauss() * 0.05;
    const dropout = d === TODAY && m >= 640 && m < 660;
    S.link[i] = dropout ? 0.4 : 6.2 + Math.sin(i / 60) * 0.5 + gauss() * 0.12;
    S.pressure[i] = 101.3 + Math.sin(i / 200) * 0.12 + gauss() * 0.02;
    S.ppo2[i] = 21.3 + Math.sin(i / 170) * 0.15 + gauss() * 0.03;
    const spe = i >= SPE_START && i < SPE_START + SPE_LEN;
    const speShape = spe ? Math.sin(((i - SPE_START) / SPE_LEN) * Math.PI) : 0;
    S.rad[i] = 74 + speShape * 310 + gauss() * 2.2;
    // environment
    labCo2 += ((2.2 + labOcc(d, m, blk.module === "lab") * (0.35 + (weak ? 0.42 : 0))) - labCo2) * 0.16;
    exVib += ((exNow ? 13 : 0) - exVib) * 0.6;
    for (const mod of MODULES) {
      const b = ENV_BASE[mod.id];
      let co2 = b.co2 + gauss() * 0.03 + (weak ? 0.12 : 0);
      let noise = b.noise + gauss() * 0.5;
      let temp = b.temp + Math.sin((m / 1440) * Math.PI * 2 - 2) * 0.35 + gauss() * 0.05;
      let hum = b.hum + Math.sin(i / 90) * 1.5 + gauss() * 0.4;
      let light = b.light;
      let vib = 1.6 + Math.abs(gauss()) * 0.25;
      if (mod.id === "lab") co2 = labCo2 + gauss() * 0.03;
      if (mod.id === "quarters") {
        if (nightQuiet) {
          co2 += 0.45;
          noise -= 1;
          light = 0;
        } else light = m > 1260 ? 90 : 140;
        if (fanOn) {
          noise += 15;
          vib += 2.1;
        }
      }
      if (mod.id === "service" && fanOn) {
        noise += 7;
        vib += 4.4;
        temp += 0.3;
      }
      if (mod.id === "node" && fanOn) noise += 4;
      if (mod.id === "exercise") {
        if (exNow) {
          co2 += 0.75;
          noise += 12;
          temp += 1.3;
          hum += 9;
        }
        vib += exVib;
      }
      if (mod.id === "galley") {
        vib += exVib * 0.32;
        if (wpaOn) noise += 4;
        if (blk.activity === "eat") {
          hum += 4;
          co2 += 0.3;
        }
      }
      if (mod.id === "node") vib += exVib * 0.12;
      if (desat) {
        vib += 16 + rnd() * 5;
        noise += 3;
      }
      if (nightQuiet && mod.id !== "quarters" && mod.id !== "service") light = Math.min(light, 40);
      if (!nightQuiet && m > 1260) light *= 0.45; // pre-sleep dimming
      S[`co2_${mod.id}`][i] = co2;
      S[`noise_${mod.id}`][i] = noise;
      S[`temp_${mod.id}`][i] = temp;
      S[`hum_${mod.id}`][i] = hum;
      S[`light_${mod.id}`][i] = Math.max(0, light + gauss() * 4);
      S[`vib_${mod.id}`][i] = vib;
    }
  }
}

// --- sleep nights -----------------------------------------------------------
export type Night = {
  day: number; // morning-of day index
  onset: number; // sample index
  wake: number;
  durationMin: number;
  quality: number;
  awakenings: number;
  fanEvent: boolean;
  lateExercise: boolean;
  noisePeak: number;
};
export const NIGHTS: Night[] = [];
for (let d = 1; d < DAYS; d++) {
  const fan = FAN_NIGHTS.has(d);
  const late = LATE_EX_DAYS.has(d - 1);
  const latency = 12 + Math.round(rnd() * 10) + (late ? 9 : 0);
  const lost = fan ? 38 + Math.round(rnd() * 22) : Math.round(rnd() * 12);
  const durationMin = 480 - latency - lost - Math.round(rnd() * 14);
  const quality = Math.round(fan ? 69 + rnd() * 5 : late ? 80 + rnd() * 3 : 84 + rnd() * 6);
  NIGHTS.push({
    day: d,
    onset: idx(d - 1, 1350 + latency),
    wake: idx(d, 390),
    durationMin,
    quality,
    awakenings: fan ? 3 + Math.round(rnd()) : 1 + Math.round(rnd() * 0.8),
    fanEvent: fan,
    lateExercise: late,
    noisePeak: Math.round(fan ? 62 + rnd() * 2 : 47 + rnd() * 2),
  });
}
// pin last night so the story is exact
{
  const n = NIGHTS[NIGHTS.length - 1];
  n.quality = 71;
  n.durationMin = 372; // 6h 12m
  n.awakenings = 3;
  n.noisePeak = 63;
}
export const nightOf = (day: number) => NIGHTS.find((n) => n.day === day);

// --- pass 2: physiology -----------------------------------------------------
const ACT_HR: Record<Activity, number> = {
  sleep: 52, eat: 68, exercise: 132, research: 66, maintenance: 76, comms: 66, medical: 62,
  personal: 61, evaprep: 81, admin: 64,
};
const ACT_HRV: Record<Activity, number> = {
  sleep: 68, eat: 50, exercise: 17, research: 52, maintenance: 44, comms: 50, medical: 55,
  personal: 57, evaprep: 41, admin: 53,
};
export const hypnogram: Uint8Array = new Uint8Array(N); // 0 awake 1 light 2 deep 3 REM
{
  let hr = 60;
  let hrv = 55;
  for (let i = 0; i < N; i++) {
    const d = dayOf(i);
    const m = minOf(i);
    const blk = blockAt(i);
    const night = nightOf(m < 720 ? d : d + 1);
    const lastNight = nightOf(d);
    const debt = lastNight ? Math.max(0, (84 - lastNight.quality) / 14) : 0; // 0..1
    const where = blk.module;
    const co2Lag = i >= 12 ? Math.max(0, S[`co2_${blockAt(i - 12).module}`][i - 12] - 2.7) : 0;
    const fanWake = FAN_NIGHTS.has(d) && m >= 120 && m < 170; // arousal 02:00–02:50
    const desatHit = d === TODAY && m >= 640 && m < 690;
    let tHr = ACT_HR[blk.activity] + debt * 3 + co2Lag * 2;
    let tHrv = ACT_HRV[blk.activity] - debt * 7 - co2Lag * 9;
    let move = 0;
    let stage = 0;
    const asleep = blk.activity === "sleep" && (!night || i >= night.onset || m < 720);
    if (blk.activity === "sleep") {
      const sinceOnset = night ? i - night.onset : 20;
      if (!asleep || sinceOnset < 0) {
        stage = 0;
        move = 22 + rnd() * 20;
        tHr = 58;
      } else {
        const cyc = (sinceOnset % 9) / 9; // ~90 min cycles
        stage = cyc < 0.15 ? 1 : cyc < 0.5 ? (sinceOnset < 30 ? 2 : 1 + (rnd() > 0.45 ? 1 : 0)) : cyc < 0.75 ? 1 : 3;
        move = 1.5 + rnd() * 3 + (stage === 1 ? 2 : 0);
        if (rnd() > 0.985) {
          move += 30;
          stage = 0;
        }
        if (fanWake) {
          const ph = (m - 120) / 50;
          stage = ph > 0.15 && ph < 0.75 ? 0 : 1;
          move = stage === 0 ? 48 + rnd() * 34 : 14 + rnd() * 8;
          tHr = stage === 0 ? 67 : 58;
          tHrv = 46;
        }
      }
    } else {
      move =
        blk.activity === "exercise" ? 420 + rnd() * 80 : blk.activity === "maintenance" ? 150 + rnd() * 60 :
        blk.activity === "evaprep" ? 170 + rnd() * 50 : 60 + rnd() * 50;
    }
    hypnogram[i] = stage;
    if (desatHit) {
      const ph = (m - 640) / 50;
      tHr += 24 * Math.max(0, 1 - ph);
      tHrv -= 14 * Math.max(0, 1 - ph);
    }
    const k = blk.activity === "exercise" ? 0.45 : 0.55;
    hr += (tHr - hr) * k;
    hrv += (tHrv - hrv) * 0.5;
    S.hr[i] = hr + gauss() * 1.4;
    S.hrv[i] = Math.max(9, hrv + gauss() * 2.2);
    S.resp[i] =
      (blk.activity === "sleep" ? 13 : blk.activity === "exercise" ? 29 : 15.5) + (hr - tHr) * 0.02 +
      gauss() * 0.5 + (S[`co2_${where}`][i] - 2.4) * 0.6;
    S.spo2[i] = Math.min(100, 97.2 - (blk.activity === "sleep" ? 0.8 : 0) + gauss() * 0.35);
    S.temp[i] =
      36.62 + Math.sin(((m - 600) / 1440) * Math.PI * 2) * 0.32 + (blk.activity === "exercise" ? 0.55 : 0) +
      gauss() * 0.04;
    S.move[i] = move;
    // derived indices (0–100). Context-corrected: exercise is not counted as stress.
    const expectedHr = ACT_HR[blk.activity];
    const strain = Math.max(0, S.hr[i] - expectedHr) * 1.6 + Math.max(0, ACT_HRV[blk.activity] - S.hrv[i]) * 0.9;
    S.stress[i] = Math.max(6, Math.min(96, (blk.activity === "sleep" ? 10 : 24) + strain + debt * 5 + gauss() * 2));
    const awakeH = m >= 390 ? (m - 390) / 60 : 0;
    S.fatigue[i] =
      blk.activity === "sleep" ? Math.max(8, 30 - m / 30) : Math.min(95, 20 + awakeH * 2.6 + debt * 22 + gauss() * 1.5);
  }
}

