// ------------------------------------------------------------------ helpers --
export const mean = (a: ArrayLike<number>, i0: number, i1: number) => {
  let s = 0;
  let n = 0;
  for (let i = Math.max(0, i0); i < Math.min(a.length, i1); i++) {
    s += a[i];
    n++;
  }
  return n ? s / n : NaN;
};
export const maxIn = (a: ArrayLike<number>, i0: number, i1: number) => {
  let v = -Infinity;
  for (let i = Math.max(0, i0); i < Math.min(a.length, i1); i++) if (a[i] > v) v = a[i];
  return v;
};
/** Mean of a signal over the same clock window on previous days (personal baseline). */
export function baseline(id: string, i: number, span = 6, days = 14): number {
  let s = 0;
  let n = 0;
  for (let k = 1; k <= days; k++) {
    const j = i - k * PER_DAY;
    if (j - span < 0) break;
    s += mean(S[id], j - span, j + 1);
    n++;
  }
  return n ? s / n : NaN;
}
export const current = (id: string, span = 3) => mean(S[id], NOW - span + 1, NOW + 1);

/** Pearson r between a (shifted later by `lag` samples) and b over [i0,i1). */
export function pearson(a: ArrayLike<number>, b: ArrayLike<number>, i0: number, i1: number, lag = 0): number {
  let n = 0, sa = 0, sb = 0, saa = 0, sbb = 0, sab = 0;
  for (let i = Math.max(0, i0); i < Math.min(N, i1, NOW + 1); i++) {
    const j = i - lag;
    if (j < 0 || j > NOW) continue;
    const x = a[j], y = b[i];
    n++; sa += x; sb += y; saa += x * x; sbb += y * y; sab += x * y;
  }
  if (n < 8) return NaN;
  const den = Math.sqrt((n * saa - sa * sa) * (n * sbb - sb * sb));
  return den ? (n * sab - sa * sb) / den : NaN;
}

